# Legacy / alias URL -> current path (301) reference map.
#
# NOTE: As of Oct 2026 these redirects are enforced authoritatively in the
# FastAPI SSR layer (backend/ssr.py REDIRECTS + old-job handling), so nginx does
# not need this map to function. It is kept as documentation and for Search
# Console review. Old individual job URLs 301 to /careers/<slug> only when an
# active role with that slug exists; otherwise they return HTTP 410 (Gone).
#
# old path                              -> new path (301)
/about-us/                              -> /about
/help-desk-support/                     -> /services/managed-it
/healthcare/                            -> /industries/healthcare
/terms-conditions/                      -> /terms-of-service
/contact-us/                            -> /contact
/jobs/                                  -> /careers
/job-openings/                          -> /careers
/services/managed-support/              -> /services/managed-it
/services/managed-it-services/          -> /services/managed-it
/services/ai-automation/                -> /services/ai
#
# Old job detail URLs (301 to /careers/<slug> if the role is open, else 301 to /careers):
/jobs/sales-representative/             -> /careers/sales-representative (or /careers)
/jobs/it-support-level-2/               -> /careers/it-support-level-2 (or /careers)
/jobs/it-project-manager/               -> /careers/it-project-manager (or /careers)
/jobs/accounting-specialist/            -> /careers
/jobs/accounting-and-administrative-assistant/ -> /careers
/jobs/feed/                             -> 410 (the old job feed is gone, not moved)
#
# Added 19 Nov 2026 from Search Console (Pages > Not found (404), and old addresses still indexed
# or crawled). Old addresses are matched in lower case, so /Home works too.
/privacy/                               -> /privacy-policy
/Home                                   -> /
/non-profit-organizations/              -> /industries/non-profit
/legal-professional-services/           -> /industries/professional-services
/banking-finance/                       -> /industries/financial-services
/cyber-security/                        -> /services/cybersecurity
/cloud-services/                        -> /services/cloud
/application-cloud-support/             -> /services/cloud
/infrastructure-management/             -> /services/remote-monitoring-management
/strategic-projects/                    -> /services/vcio-vciso
/cost-calculator/                       -> /contact
/cookie-policy/                         -> /privacy-policy
/job-location/<anything>/               -> /careers
/job-category/<anything>/               -> /careers
/job-type/<anything>/                   -> /careers
/services                               -> /            (no services index page; in the breadcrumb trail)
/case-studies                           -> /resources   (no case-study index page; in the breadcrumb trail)
/service-areas                          -> /service-areas/new-york
#
# Any other address ending in "/" (for example /careers/) 301s to the same address without it.
#
# Served by nginx, not redirected: /briefs/*.pdf (the "pdf" extension must be in the static-file
# location in nginx-intrinsic.conf; without it these downloads return 404).
#
# Not real pages, left as 404: /wp-admin/admin-ajax.php, /wp-admin/*, /*
#
# Unknown/retired pages not listed here return a genuine HTTP 404.
